#!/usr/bin/env python3
"""Check local links and GitHub-style anchors in tracked Markdown files."""

import re
import subprocess
import sys
from collections import Counter
from html import unescape
from pathlib import Path, PurePosixPath
from urllib.parse import unquote

ROOT = Path(__file__).resolve().parent.parent
SKIP_DIRS = {
    ".git",
    ".next",
    ".scratch",
    ".svelte-kit",
    ".venv",
    "autogenerated",
    "build",
    "coverage",
    "dist",
    "generated",
    "node_modules",
    "pkg",
    "target",
    "vendor",
}
REFERENCE_RE = re.compile(
    r"^ {0,3}\[[^]]+\]:\s*"
    r"(?:<(?P<bracket>(?:\\.|[^>])*)>|(?P<bare>\S+))"
    r"(?:\s+(?:\"(?:\\.|[^\"])*\"|'(?:\\.|[^'])*'|\((?:\\.|[^)])*\)))?"
    r"\s*$"
)
ATX_HEADING_RE = re.compile(r"^ {0,3}#{1,6}[ \t]+(.+?)[ \t]*$")
SETEXT_HEADING_RE = re.compile(r"^ {0,3}(?:=+|-+)[ \t]*$")
FENCE_RE = re.compile(r"^ {0,3}(`{3,}|~{3,})")
SCHEME_RE = re.compile(r"^[A-Za-z][A-Za-z0-9+.-]*:")
ESCAPABLE_RE = re.compile(r"\\([!\"#$%&'()*+,./:;<=>?@\[\\\]^_`{|}~-])")


def skipped(path: PurePosixPath) -> bool:
    return any(part in SKIP_DIRS for part in path.parts)


def tracked_markdown() -> list[Path]:
    result = subprocess.run(
        [
            "git",
            "ls-files",
            "-z",
            "--cached",
            "--others",
            "--exclude-standard",
            "--",
            "*.md",
        ],
        cwd=ROOT,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )
    if result.returncode:
        raise RuntimeError(result.stderr.strip() or "git ls-files failed")
    paths = []
    for name in result.stdout.split("\0"):
        if not name:
            continue
        path = PurePosixPath(name)
        candidate = ROOT / path
        if not skipped(path) and candidate.is_file():
            paths.append(candidate)
    return sorted(paths)


def visible_lines(text: str, *, inline_code: bool = True) -> list[str]:
    """Remove fenced code and optionally inline code without changing line numbers."""
    lines = []
    fence = ""
    for line in text.splitlines():
        match = FENCE_RE.match(line)
        if match:
            marker = match.group(1)
            if not fence:
                fence = marker
            elif marker[0] == fence[0] and len(marker) >= len(fence):
                fence = ""
            lines.append("")
            continue
        if fence:
            lines.append("")
            continue
        line = re.sub(r"<!--.*?-->", "", line)
        if inline_code:
            line = re.sub(r"(`+).*?\1", lambda m: " " * len(m.group(0)), line)
        lines.append(line)
    return lines


def closing_parenthesis(line: str, start: int) -> int | None:
    depth = 1
    angle = False
    quote = ""
    index = start
    while index < len(line):
        char = line[index]
        if char == "\\":
            index += 2
            continue
        if quote:
            if char == quote:
                quote = ""
        elif angle:
            if char == ">":
                angle = False
        elif char == "<":
            angle = True
        elif char in "'\"" and index > start and line[index - 1].isspace():
            quote = char
        elif char == "(":
            depth += 1
        elif char == ")":
            depth -= 1
            if depth == 0:
                return index
        index += 1
    return None


def inline_destination(body: str) -> str:
    body = body.strip()
    if not body:
        return ""
    if body.startswith("<"):
        match = re.match(r"<((?:\\.|[^>])*)>", body)
        return match.group(1) if match else ""
    return body.split(maxsplit=1)[0]


def links(text: str):
    for line_number, line in enumerate(visible_lines(text), 1):
        reference = REFERENCE_RE.match(line)
        if reference:
            yield line_number, reference.group("bracket") or reference.group("bare")
            continue
        position = 0
        while True:
            start = line.find("](", position)
            if start < 0:
                break
            if start and line[start - 1] == "\\":
                position = start + 2
                continue
            end = closing_parenthesis(line, start + 2)
            if end is None:
                break
            destination = inline_destination(line[start + 2 : end])
            if destination:
                yield line_number, destination
            position = end + 1


def heading_text(text: str) -> str:
    text = re.sub(r"!\[([^]]*)\]\([^)]*\)", r"\1", text)
    text = re.sub(r"\[([^]]+)\]\([^)]*\)", r"\1", text)
    text = re.sub(r"\[([^]]+)\]\[[^]]*\]", r"\1", text)
    text = re.sub(r"</?[^>]+>", "", text)
    text = ESCAPABLE_RE.sub(r"\1", unescape(text))
    return text.replace("`", "").replace("*", "").replace("~", "")


def github_slug(text: str) -> str:
    slug = []
    for char in heading_text(text).strip().lower():
        if char.isalnum() or char in "-_":
            slug.append(char)
        elif char.isspace():
            slug.append("-")
    return "".join(slug)


def anchors(text: str) -> set[str]:
    result = set()
    occurrences = Counter()
    previous = ""
    for line in visible_lines(text, inline_code=False):
        for match in re.finditer(r"<a\s+[^>]*(?:id|name)=[\"']([^\"']+)", line, re.I):
            result.add(unescape(match.group(1)))
        match = ATX_HEADING_RE.match(line)
        if match:
            title = re.sub(r"[ \t]+#+[ \t]*$", "", match.group(1))
        elif SETEXT_HEADING_RE.match(line) and previous.strip():
            title = previous.strip()
        else:
            previous = line
            continue
        slug = github_slug(title)
        if slug:
            occurrence = occurrences[slug]
            occurrences[slug] += 1
            result.add(slug if occurrence == 0 else f"{slug}-{occurrence}")
        previous = line
    return result


def clean_destination(destination: str) -> str:
    return unescape(ESCAPABLE_RE.sub(r"\1", destination.strip()))


def check_link(
    source: Path, destination: str, anchor_cache: dict[Path, set[str]]
) -> str | None:
    destination = clean_destination(destination)
    if not destination or destination.startswith("//") or SCHEME_RE.match(destination):
        return None
    path_part, separator, fragment = destination.partition("#")
    path_part = unquote(path_part.partition("?")[0])
    fragment = unquote(fragment) if separator else ""

    if path_part:
        candidate = (
            ROOT / path_part.lstrip("/")
            if path_part.startswith("/")
            else source.parent / path_part
        )
    else:
        candidate = source
    try:
        target = candidate.resolve()
        relative = target.relative_to(ROOT)
    except (OSError, ValueError):
        return f"local target leaves the repository: {destination}"
    if ".scratch" in relative.parts:
        return f"stable documentation must not link into .scratch: {destination}"
    if not target.exists():
        return f"missing local target: {destination}"
    if target.is_dir():
        if not fragment:
            return None
        target = target / "README.md"
        if not target.is_file():
            return f"directory has no README.md for anchor: {destination}"
        relative = target.relative_to(ROOT)
    if fragment and target.suffix.lower() in {".md", ".markdown"}:
        if target not in anchor_cache:
            anchor_cache[target] = anchors(
                target.read_text(encoding="utf-8-sig", errors="replace")
            )
        if fragment not in anchor_cache[target]:
            return f"missing anchor '#{fragment}' in {relative.as_posix()}"
    return None


def main() -> int:
    try:
        documents = tracked_markdown()
    except (OSError, RuntimeError) as error:
        print(f"scripts/check_docs.py:1: {error}", file=sys.stderr)
        return 2

    errors = []
    anchor_cache = {}
    for document in documents:
        source = document.relative_to(ROOT).as_posix()
        try:
            text = document.read_text(encoding="utf-8-sig", errors="replace")
        except OSError as error:
            errors.append(f"{source}:1: cannot read file: {error}")
            continue
        for line_number, destination in links(text):
            try:
                error = check_link(document, destination, anchor_cache)
            except OSError as error:
                error = f"cannot read link target: {error}"
            if error:
                errors.append(f"{source}:{line_number}: {error}")

    if errors:
        print("\n".join(errors), file=sys.stderr)
        print(
            f"Documentation check failed with {len(errors)} error(s).", file=sys.stderr
        )
        return 1
    print(f"Checked {len(documents)} Markdown files: no broken local links.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
